import{_ as a,C as n,o as s,c as r,j as t,a as i,E as c,ak as d}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"Browser extension","description":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance.","frontmatter":{"title":"Browser extension","description":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/extension.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/extension.html"}],["meta",{"property":"og:title","content":"Browser extension | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance."}]]},"headers":[],"relativePath":"features/extension.md","filePath":"features/extension.md","lastUpdated":1790492021000}'),h={name:"features/extension.md"};function l(p,e,g,u,m,f){const o=n("Needs");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"browser-extension",tabindex:"-1"},[i("Browser extension "),t("a",{class:"header-anchor",href:"#browser-extension","aria-label":'Permalink to "Browser extension"'},"​")],-1)),c(o,{extension:""}),e[1]||(e[1]=d('<p>Piwi Picker is a Chrome and Edge extension (Manifest V3) that picks ranked, stable Playwright locators from the page you are looking at, scored by the same engine the dashboard uses, and records a multi-page flow into a runnable TypeScript spec. It works standalone and sends nothing by default; connecting it to a Piwi instance adds what needs your project&#39;s history.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Every tool below runs on the live page, from the toolbar popup. The last three need a <a href="#connecting-to-a-piwi-instance">connection to a Piwi instance</a>; the others never reach a network.</p><table tabindex="0"><thead><tr><th>Tool</th><th>For</th></tr></thead><tbody><tr><td><a href="#pick-an-element">Pick an element</a></td><td>a ranked locator for one element, re-checked against the page</td></tr><tr><td><a href="#hover-inspect">Hover-inspect</a></td><td>the best locator of whatever the pointer is on</td></tr><tr><td><a href="#locator-console">Locator console</a></td><td>what a locator expression matches right now</td></tr><tr><td><a href="#multi-pick">Multi-pick</a></td><td>the shared pattern of a list&#39;s rows or cards</td></tr><tr><td><a href="#lint-overlay">Lint overlay</a></td><td>the elements that would make bad locator targets</td></tr><tr><td><a href="#assertion-suggester">Assertion suggester</a></td><td><code>expect(...)</code> lines for an element</td></tr><tr><td><a href="#session">Session</a></td><td>named elements across pages, exported as a page object</td></tr><tr><td><a href="#copy-context-for-agent">Copy context for agent</a></td><td>one block about an element for a coding agent</td></tr><tr><td><a href="#record-actions">Record actions</a></td><td>a runnable spec from clicks and fills across pages</td></tr><tr><td><a href="#matching-functions">Matching functions</a></td><td>a recording that calls your own functions</td></tr><tr><td><a href="#test-functions-against-this-page">Test functions</a></td><td>which of your functions work on this page</td></tr><tr><td><a href="#tested-elements">Tested elements</a></td><td>which elements of this page your tests reach</td></tr></tbody></table><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>Install <strong><a href="https://chromewebstore.google.com/detail/piwi-picker/pakhnokpjboejcghgcmkjlpnogfjihhe" target="_blank" rel="noreferrer">Piwi Picker from the Chrome Web Store ↗</a></strong>. The same listing covers Edge and the other Chromium browsers; in Edge, click <strong>Allow</strong> on the <em>Allow extensions from other stores</em> banner once, then <strong>Get</strong>.</p><p>Every tool in the popup has a key shown on its tile (<code>1</code> records, <code>2</code> picks, <code>T</code> opens Tested elements). One tool runs at a time and <strong>Esc</strong> cancels it; recording is the exception and runs until its own <strong>Stop</strong>.</p><p>Picking also has a shortcut without the popup, suggested as <code>Ctrl+Shift+E</code> (<code>Cmd+Shift+E</code> on macOS). A browser leaves it unbound when another extension holds it; the popup footer shows the key actually bound.</p><h2 id="pick-an-element" tabindex="-1">Pick an element <a class="header-anchor" href="#pick-an-element" aria-label="Permalink to &quot;Pick an element&quot;">​</a></h2><p>Hover highlights, a click picks. The pick snaps to the nearest actionable ancestor (the text inside a button picks the button), and ↑/↓ walk the DOM tree first, showing the locator each step would produce. For an element with a role, an <strong>anchors</strong> step lets you pick stable parents to scope the locator to, with a live match count.</p><p>Every candidate is scored the way the dashboard scores captured locators, then counted again against the page as it is now. A candidate that matches several elements shows its count and a suggestion (<code>.first()</code>, <code>.filter({ hasText: … })</code>), and ranks below every candidate that matches exactly one, so <code>getByTestId(&#39;product-43&#39;).getByRole(&#39;button&#39;)</code> beats a <code>getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code> that hits every card. Parents are anchored on the hook they carry (<code>data-testid</code>, <code>id</code>, a landmark role, an app-specific <code>data-*</code>), and a repeated container with no hook is singled out by its heading: <code>getByRole(&#39;listitem&#39;).filter({ hasText: &#39;Keyboard&#39; }).getByRole(&#39;button&#39;)</code>.</p><p>Copy the result as the bare locator, an action line (<code>await page.getByRole(…).click();</code>) or a visibility assertion; the popup remembers the last form. <strong>Copy all</strong> copies every ranked locator, one per line, for a project&#39;s <a href="./locator-usage.html#the-locators-page">Locators page</a>.</p><h2 id="hover-inspect" tabindex="-1">Hover-inspect <a class="header-anchor" href="#hover-inspect" aria-label="Permalink to &quot;Hover-inspect&quot;">​</a></h2><p>Toggled from the popup: hover any element to see its best-ranked locator in a tooltip, with no click.</p><h2 id="locator-console" tabindex="-1">Locator console <a class="header-anchor" href="#locator-console" aria-label="Permalink to &quot;Locator console&quot;">​</a></h2><p>Type or paste a locator expression and every match is outlined on the page as you type, with a strict-mode verdict: green for a single match, amber and numbered for several. It parses a safe subset (<code>getBy*</code> chains, <code>locator(css)</code>, <code>filter({ hasText })</code>, <code>.first()</code>, <code>.last()</code>, <code>.nth()</code>) and never runs it as code.</p><h2 id="multi-pick" tabindex="-1">Multi-pick <a class="header-anchor" href="#multi-pick" aria-label="Permalink to &quot;Multi-pick&quot;">​</a></h2><p>Pick two or three similar items, such as table rows or cards, to derive the pattern they share (for example <code>getByRole(&#39;row&#39;).filter({ hasText: … })</code>). It warns when only <code>.nth()</code> could tell them apart.</p><h2 id="lint-overlay" tabindex="-1">Lint overlay <a class="header-anchor" href="#lint-overlay" aria-label="Permalink to &quot;Lint overlay&quot;">​</a></h2><p>One click outlines every interactive element that would score badly as a locator target (no test id, no accessible name, no stable parent), with a suggested <code>data-testid</code> for each and a Markdown checklist to export.</p><h2 id="assertion-suggester" tabindex="-1">Assertion suggester <a class="header-anchor" href="#assertion-suggester" aria-label="Permalink to &quot;Assertion suggester&quot;">​</a></h2><p>Pick an element to get the <code>expect(...)</code> candidates that apply to it (<code>toHaveValue</code>, <code>toHaveText</code>, <code>toHaveAccessibleName</code>, <code>toBeVisible</code>), built on its top-ranked locator, each with a copy button.</p><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><p>Pick and name elements as you browse, across pages, then export the list as a page-object fixture class, a Markdown table for a pull request or an issue, or JSON. The session lasts until the browser closes.</p><h2 id="copy-context-for-agent" tabindex="-1">Copy context for agent <a class="header-anchor" href="#copy-context-for-agent" aria-label="Permalink to &quot;Copy context for agent&quot;">​</a></h2><p>Pick an element to copy one block for a coding agent: the page URL, a summary of the element (tag, role, accessible name, key attributes, text) and every ranked locator.</p><h2 id="record-actions" tabindex="-1">Record actions <a class="header-anchor" href="#record-actions" aria-label="Permalink to &quot;Record actions&quot;">​</a></h2><p><strong>Record actions</strong> asks for access to the one site you are on, then captures clicks, fills, checks, select changes and Enter-to-submit across that site&#39;s pages. A red border marks the recorded tab, and a small overlay counts the steps and shows the locator of the last one. <strong>Stop</strong> opens the review: <strong>Copy as TypeScript</strong> for a runnable spec (<code>page.goto</code>, then one line per step), or <strong>Discard</strong>. Password values are never captured; the spec reads a <code>process.env.*</code> placeholder instead.</p><h2 id="matching-functions" tabindex="-1">Matching functions <a class="header-anchor" href="#matching-functions" aria-label="Permalink to &quot;Matching functions&quot;">​</a></h2><p>With a connection, the recorder loads the <a href="./test-functions.html">function catalog</a> of the project mapped to the page: the page-object methods and helpers you registered. While recording, the overlay ranks which function the steps so far look like, with a progress count (<code>2/3</code>) until one matches in full. On export, a complete match becomes a call to your function; unmatched steps stay plain locator lines. The matcher only chooses among the functions you registered, never invents one, and scores DOM patterns without AI.</p><h2 id="test-functions-against-this-page" tabindex="-1">Test functions against this page <a class="header-anchor" href="#test-functions-against-this-page" aria-label="Permalink to &quot;Test functions against this page&quot;">​</a></h2><p><strong>Test functions</strong> in the popup scores every function of the active project&#39;s catalog against the page as it is now: <strong>ready to use here</strong> (every step resolves to one element), <strong>partial match</strong>, or <strong>not found on this page</strong>. No recording is needed. <strong>Manage catalog in Piwi ↗</strong> opens the project&#39;s Test functions page.</p><h2 id="tested-elements" tabindex="-1">Tested elements <a class="header-anchor" href="#tested-elements" aria-label="Permalink to &quot;Tested elements&quot;">​</a></h2><p>With a connection, <a href="./tested-elements.html">Tested elements</a> outlines every element of the page a test of the active project reaches, lists those tests, and marks the buttons, links and fields no test reaches.</p><h2 id="permissions-explained" tabindex="-1">Permissions, explained <a class="header-anchor" href="#permissions-explained" aria-label="Permalink to &quot;Permissions, explained&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>activeTab</code></td><td>acts on the tab you are looking at, only when you click the toolbar icon or press the shortcut</td></tr><tr><td><code>scripting</code></td><td>injects the picker or the recorder into that tab on demand; no content script runs on pages you did not ask it to</td></tr><tr><td><code>storage</code></td><td>keeps your copy format and, only if you connect, the instance URL, API key, project mappings, cached catalogs and the last three <a href="./tested-elements.html">locator indexes</a>, on your machine. The session and the running recording use <code>chrome.storage.session</code>, cleared when the browser closes</td></tr><tr><td><code>optional_host_permissions</code> (none granted in advance)</td><td>recording asks for the one site you are on, to follow you across its pages; a connection asks for your instance&#39;s origin. Never <code>&lt;all_urls&gt;</code></td></tr></tbody></table><h2 id="connecting-to-a-piwi-instance" tabindex="-1">Connecting to a Piwi instance <a class="header-anchor" href="#connecting-to-a-piwi-instance" aria-label="Permalink to &quot;Connecting to a Piwi instance&quot;">​</a></h2><p>Optional and off by default. The popup&#39;s gear button opens the settings: your instance&#39;s URL, an API key (<code>pd_…</code>, from your account&#39;s API key settings), and a <strong>Project mappings</strong> table of URL patterns and projects (<code>*</code> matches within one path segment, <code>**</code> across segments, as in <code>https://shop.example.com/**</code>). Saving fetches each mapped project&#39;s function catalog and caches it; the request carries nothing about your browsing beyond the project ids.</p><p>The cache refreshes in the background, once per recorded page and when a recording stops; <strong>Refresh</strong> in Test functions fetches it now. The first mapping that matches the page applies, and the popup&#39;s <strong>Active project</strong> select overrides it for the current tab.</p><p><strong>A recording is never sent to your instance.</strong> Connecting changes only what <strong>Copy as TypeScript</strong> produces and what the overlay shows while recording.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>One frame at a time.</strong> The picker and the recorder see the top-level document, not iframes or shadow DOM.</li><li><strong>Recording covers one origin.</strong> On another site, recording stops capturing steps; stop and review, or start again there.</li><li><strong>No aria-snapshot copier.</strong> <code>toMatchAriaSnapshot()</code> YAML needs the computed accessibility tree, which an extension reaches only with the <code>debugger</code> permission.</li><li><strong>Live re-check covers the common shapes.</strong> <code>getByTestId</code>, CSS and a bare <code>getByRole</code> are counted again against the page; text, label and placeholder matches and anchored chains keep the count from the pick.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: from a failing locator to the one to use instead</li><li><a href="./tested-elements.html">Tested elements</a>: the elements your tests reach, drawn on the page</li><li><a href="./test-functions.html">Test functions catalog</a>: the functions a recording can call</li><li><a href="./locator-healing.html">Locator healing</a>: the replacement Piwi proposes after a failure</li></ul>',44))])}const k=a(h,[["render",l]]);export{y as __pageData,k as default};
